css:
.action-banner a[href*="frappe.utils.print_format.download_pdf"] {
    display: none !important;
}

.worksheet{
    margin:auto;
    padding: 0;
    min-width: 8.5in;
    height: 14.25in;
    border: 10px solid white;
}

.content{
    display:inline-block;
    transform-origin: top left;
}

#notice{
    display:none;
}

.show-notice .worksheet,
.show-notice .page-break{
    display:none !important;
}

.show-notice #notice{
    display: block !important;
}

#pseudo-content{
    text-wrap:nowrap;
    display:inline;
    visibility:hidden;
}

.print-format{
    max-width: 8.5in;
    min-height: 14.25in;
    padding:0!important;
}

.worksheet td, .worksheet th{
    padding:0 0 0 1px!important;
}

.checkbox{
    margin-left: 7px !important;
    font-size: larger;
    display: inline;
}

@media print {
    @page{
        margin:0.2in;
        size:A4;
    }

    html,body{
        max-width: fit-content;
    }
    
    html,body,.print-format-gutter, .print-format{
        margin:0;
        padding:0;
    }
    
    .print-format{
        max-width:100%;
    }
}

.nowrap-col{white-space:nowrap !important;}

.extra-sheet{height:auto !important;}

td.merged{display: none !important;}

[x-cloak] { visibility: hidden !important; }

img#id-placeholder{width:70% !important}

tr.R-Signature{height:31px !important;}
