{% from 'cvsu_hris/templates/includes/show_checkbox.html.jinja' import show_checkbox %}
<div class='show-notice'>
    <div id='notice' style="margin-top: 70px !important;">
        <img src="/assets/cvsu_hris/images/CvSU.png" style="height: 150px; margin-right: auto; margin-left: auto; display: block; ">
        <p style="font-size: 30pt; text-align: center; line-height: 1;">Please Click Full Page for Preview</p>
        <hr style="margin:auto;width:80%">
        <p style="padding-top: 10px; font-size:15pt; font-family: Courier; font-weight: bold; text-align: center; line-height: 1;">Personal Data Sheet (PDS)</p>
    </div>
    <div x-cloak> 
        {% set main_sheet_count = 4 %}
        {% for page in range(1,main_sheet_count + 1) %}
        {% set ws = 'templates/pages/pds/ws{page}.html.jinja'.format(page=page) %}
        {% include ws %}
        {%if main_sheet_count < 4 %}
            <div class="page-break"></div>
        {% endif %}
        {% endfor %}
    
        {% set extra_sheet_count = 13 %}
        {% for page in range(main_sheet_count + 1, extra_sheet_count + 1) %}
        {% set ws = 'templates/pages/pds/ws{page}.html.jinja'.format(page=page) %}
        {% include ws %}

        {% endfor %}
    
        <div id="pseudo-content"></div>
    </div>
</div>
{% include 'templates/pages/pds/ws_load_data.html.jinja' %}
{{ include_script('pds.bundle.js') }}
